from pathlib import Path
import json

root=Path(__file__).resolve().parents[1]
colors=json.loads((root/'brand-colors.json').read_text())
sizes=[16,20,24,32,40,48,64,96,128]
def image(src,alt,style=''):
 return f'<img src="../{src}" alt="{alt}" style="{style}">'
def ladder(kind):
 return '<div class="ladder">'+''.join(f'<div><span>{n} px</span>{image(f"tests/scale/{kind}-{n}.png",f"{kind} {n} px",f"width:{n}px;height:auto")}</div>' for n in sizes)+'</div>'
def pixels(kind):
 return '<div class="pixels">'+''.join(f'<div><span>{n} px · ×4</span>{image(f"tests/scale/{kind}-{n}.png",f"{kind}, пиксельная сетка {n}",f"width:{n*4}px;height:auto;image-rendering:pixelated")}</div>' for n in [16,24,32,48])+'</div>'
matrix=''.join(f'<tr><td>{c["foreground"]} / {c["background"]}</td><td>{c["ratio"]:.2f}:1</td><td>{c["use"]}</td></tr>' for c in colors['combinations'])
html='''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" href="../favicon/favicon.svg" type="image/svg+xml"><title>Zolotoy · Brand asset review</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#111310;color:#eef0eb;font:15px/1.55 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}main{max-width:1280px;margin:auto;padding:40px 32px}h1{font-size:36px;letter-spacing:-1px;font-weight:550;margin:12px 0}h2{font-size:21px;font-weight:500;margin:6px 0 20px}h3{font-size:16px;font-weight:500}.tag{font:12px monospace;letter-spacing:1.4px;color:#acbea1}p,.note{color:#aeb3a7}.hero{background:#1d1c1b;border:1px solid #363b32;padding:36px 100px;border-radius:8px;margin:26px 0}.hero img{display:block;width:100%;height:auto}section{margin-top:30px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.card{background:#1d1f1b;border:1px solid #363b32;border-radius:8px;padding:24px;min-width:0}.card img.wide{width:100%;height:auto;display:block}.light{background:#fff;color:#1d1c1b}.light p{color:#555}.light .tag{color:#57604f}.gray{background:#808080}.swatches{display:flex;gap:14px;flex-wrap:wrap}.swatch{width:calc(25% - 11px);min-width:120px}.color{height:70px;border:1px solid #777;border-radius:4px;margin-bottom:7px}.ladder{display:flex;align-items:flex-start;gap:22px;overflow:auto;min-height:126px;padding-bottom:14px}.ladder>div{min-width:30px;flex:none}.ladder span,.pixels span{display:block;font:11px monospace;color:#bac3b0;margin-bottom:20px}.ladder img{display:block;max-width:none}.pixels{display:flex;align-items:flex-start;gap:25px;overflow:auto;min-height:150px}.pixels>div{flex:none}.avatars{display:flex;justify-content:space-around;align-items:center;gap:20px;flex-wrap:wrap}.avatars figure{margin:10px 0;text-align:center}.avatars img{display:block;width:144px;height:144px}.avatars figcaption{font-size:12px;color:#b8c2ae;margin-top:10px}.platforms{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.platform{background:#f6f7f8;color:#1d1c1b;padding:20px;border-radius:8px}.platform img{width:64px;height:64px;display:block;margin:14px 0}.platform.telegram{background:#e8f0f5}.platform.youtube{background:#fff}.platform small{color:#57605c}.icons{display:flex;gap:25px;align-items:center;min-height:70px}.icons img{display:block}.context{padding:22px;border-radius:6px}.context img{height:auto}.mono{display:flex;align-items:center;gap:24px;min-height:100px}.mono img{width:140px;height:auto}.social img{width:100%;height:auto;display:block}.links{display:flex;flex-wrap:wrap;gap:22px}a{color:#d0e4c2;text-underline-offset:4px}table{width:100%;border-collapse:collapse;font-size:13px}td,th{text-align:left;padding:9px 0;border-bottom:1px solid #41483b}.notice{border-left:2px solid #bacba9;padding-left:18px}footer{margin-top:35px;border-top:1px solid #363b32;padding:25px 0}.checkered{background-color:#747474;background-image:conic-gradient(#888 25%,transparent 0 50%,#888 0 75%,transparent 0);background-size:20px 20px}.regression{position:fixed;left:-2000px;top:0;width:1082px;background:#1d1c1b}.regression img{width:1082px;height:auto;display:block}@media(max-width:720px){main{padding:24px 16px}h1{font-size:28px}.hero{padding:24px 8px}.grid{grid-template-columns:1fr}.platforms{grid-template-columns:1fr 1fr}.card{padding:18px}.swatch{width:calc(50% - 7px)}.avatars img{width:100px;height:100px}.pixels{gap:15px}}@media print{body{background:#fff;color:#1d1c1b}.card{break-inside:avoid}.tag,p,.note{color:#444}a{color:#222}.hero{background:#1d1c1b;-webkit-print-color-adjust:exact;print-color-adjust:exact}}
</style><main><div class="tag">PRODUCTION ASSETS / MASTER APPROVED &amp; LOCKED</div><h1>Один мастер. Все контексты.</h1><p>Геометрия утверждённого SVG сохранена. Этот лист показывает цвет, размер, поля и обрезку производных материалов.</p>
'''
html+='<div class="hero">'+image('master/logo-master.svg','Утверждённый неизменный master logo')+'</div>'
html+='<div class="links"><a href="../README.md">Как использовать</a><a href="../master/logo-master.svg">Master SVG</a><a href="geometry-preview.html">Геометрия</a><a href="../tests/final-qa.md">Результаты QA</a></div>'
html+='<section><div class="tag">01 / COLOR SYSTEM</div><h2>Серебро, графит и монохром</h2><div class="swatches">'
for name,c in colors['colors'].items():html+=f'<div class="swatch"><div class="color" style="background:{c["hex"]}"></div><strong>{name}</strong><p>{c["hex"]}</p></div>'
html+='</div><div class="grid"><div class="card"><h3>Светлый знак / тёмный фон</h3>'+image('svg/logo-white.svg','Белый знак на графитовом фоне','width:100%;height:auto')+'</div><div class="card light"><h3>Графитовый знак / светлый фон</h3>'+image('svg/logo-charcoal.svg','Графитовый знак на белом фоне','width:100%;height:auto')+'</div></div>'
html+='<div class="grid"><div class="card"><h3>Измеренный контраст</h3><table><thead><tr><th>Пара</th><th>Контраст</th><th>Рекомендация</th></tr></thead><tbody>'+matrix+'</tbody></table></div><div class="card"><h3>Прозрачные варианты</h3><div class="mono context light">'+image('svg/logo-black.svg','Чёрный монохром')+'</div><div class="mono context checkered">'+image('svg/logo-white.svg','Белый монохром')+image('svg/logo-black.svg','Чёрный на сером фоне')+'</div><p class="note">На светлом фоне используйте charcoal/black. Silver предназначен для тёмного фона.</p></div></div></section>'
html+='<section class="card"><div class="tag">02 / OPTICAL SIZE</div><h2>Master и отдельная micro-версия</h2><h3>Master · исходная геометрия</h3>'+ladder('master')+pixels('master')+'<h3>Micro · только компактные контексты</h3>'+ladder('micro')+pixels('micro')+'<p class="notice">Micro расширяет три существующих негативных канала векторной маской. Исходные path мастера сохранены дословно. Обычный micro рассчитан на 24–64 px. Для favicon 16/32/48 применяется усиленная настройка. Master остаётся неизменным.</p></section>'
html+='<section class="card"><div class="tag">03 / CONTAINERS</div><h2>Единые поля, три формы</h2><div class="avatars">'
for kind in ['square','rounded-square','circle']:html+='<figure>'+image(f'avatars/{kind}/avatar-512.png',f'Аватар {kind}')+f'<figcaption>{kind} · 78% ширины</figcaption></figure>'
html+='</div><p class="note">Поля слева и справа: 11% canvas. Радиус rounded-square: 18%. Круглая обрезка сохраняет весь знак.</p></section>'
html+='<section><div class="tag">04 / PLATFORM CROP SIMULATIONS</div><h2>Примерка для платформ</h2><div class="platforms">'
for name,cls,radius,asset in [('GitHub','github','50%','github-500.png'),('LinkedIn Page','linkedin','6px','linkedin-page-400.png'),('Telegram','telegram','50%','avatar-512.png'),('YouTube','youtube','50%','youtube-800.png')]:
 html+=f'<div class="platform {cls}"><strong>{name}</strong>'+image('avatars/square/'+asset,f'{name}, локальная примерка',f'border-radius:{radius}')+'<small>Локальная модель crop</small></div>'
html+='</div><p class="note">Без загрузки в аккаунты. LinkedIn: файл для Page/бренд-контекста; это не подтверждение допустимости логотипа вместо личного фото.</p></section>'
html+='<section><div class="tag">05 / FAVICON &amp; INSTALL ICONS</div><h2>Светлая и тёмная рамка браузера</h2><div class="grid">'
for bg,cls in [('white','light'),('#181818','')]:
 html+=f'<div class="card {cls}" style="background:{bg}"><div class="icons">'+''.join(image(f'favicon/favicon-{n}x{n}.png',f'Favicon {n} px',f'width:{n}px;height:{n}px') for n in [16,32,48])+image('favicon/favicon.svg','SVG favicon','width:64px;height:64px')+'</div><p>16 / 32 / 48 / SVG</p></div>'
html+='</div><div class="grid"><div class="card"><h3>Apple touch icon</h3>'+image('favicon/apple-touch-icon.png','Apple touch icon 180 px','width:128px;height:128px;border-radius:22%')+'<p class="note">Файл квадратный и непрозрачный; скругление здесь моделирует систему.</p></div><div class="card"><h3>PWA maskable</h3>'+image('favicon/pwa-maskable-512.png','Maskable PWA, круглая маска','width:128px;height:128px;border-radius:50%')+'<p class="note">Знак находится внутри центрального круга радиусом 40% canvas.</p></div></div></section>'
html+='<section><div class="tag">06 / WEBSITE CONTEXT</div><h2>Пример использования на сайте</h2><div class="grid"><div class="card" style="background:#0b0c10"><h3>maxzolotoy.com · измеренный фон</h3>'+image('svg/logo-silver.svg','Логотип на фоне maxzolotoy.com','width:220px;max-width:100%;height:auto')+'<p>SVG width: 220px; height: auto</p></div><div class="card light"><h3>Светлый layout / CV / README</h3>'+image('svg/logo-charcoal.svg','Логотип на светлом фоне','width:220px;max-width:100%;height:auto')+'<p>Отдельный контрастный вариант</p></div></div><p class="note">zolotoy.dev не вернул доступный контекст при исследовании (HTTP 403). Сайты не изменялись.</p></section>'
html+='<section class="social"><div class="tag">07 / SOCIAL CARD</div><h2>OpenGraph · 1200 × 630</h2>'+image('social/opengraph-1200x630.png','Social card: серебряный знак на графитовом фоне')+'<p class="note">Рабочий формат social card; основной знак также целиком сохраняется в центральной квадратной обрезке.</p></section>'
html+='<footer><strong>MASTER LOGO STATUS: APPROVED / LOCKED</strong><p>Проверки и ограничения — в README и final-qa.md. Калиброванные OLED/IPS и реальные серверные преобразования платформ не тестировались.</p></footer></main></html>'
(root/'previews/brand-preview.html').write_text(html+'\n')
print('Built brand-preview.html')
